"use client";

import { Envelope as EnvelopePrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const envelopeVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-48",
      lg: "h-64",
      sm: "h-32",
    },
  },
});

interface EnvelopeProps
  extends EnvelopePrimitive.Root.Props,
    VariantProps<typeof envelopeVariants> {}

export function Envelope({ className, size, ...props }: EnvelopeProps) {
  return (
    <EnvelopePrimitive.Root
      className="w-full data-disabled:cursor-not-allowed"
      role="group"
      {...props}
    >
      <EnvelopePrimitive.Graph
        className={cn(
          "rounded-none border border-transparent bg-card shadow-sm ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-2 hover:ring-ring/30 has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring/30 active:ring-2 active:ring-ring/30 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none w-full touch-none select-none overflow-hidden",
          "data-disabled:pointer-events-none data-disabled:opacity-50",
          envelopeVariants({ size }),
          className
        )}
        data-slot="envelope"
      >
        <EnvelopePrimitive.Fill className="fill-primary/15 stroke-none" />
        <EnvelopePrimitive.Line className="stroke-primary stroke-2" />
      </EnvelopePrimitive.Graph>
      <EnvelopePrimitive.Points>
        {(_point, index, points) => (
          <EnvelopePrimitive.Point
            aria-label={`Point ${index + 1} of ${points.length}`}
            className="bg-primary size-3.5 transition-colors hover:ring-2 hover:ring-ring/30 focus-visible:ring-2 focus-visible:ring-ring/30 active:ring-2 active:ring-ring/30 data-disabled:pointer-events-none motion-reduce:transition-none cursor-grab touch-none select-none outline-none active:cursor-grabbing"
            index={index}
            key={index}
          />
        )}
      </EnvelopePrimitive.Points>
    </EnvelopePrimitive.Root>
  );
}
